    def _q2_write_atomic(self, varfile):
        # q2-save-variables-atomic (Q2 tweaked): the stock code truncated the file and then wrote it in place, so a
        # power cut at that moment could leave an empty or half-written file (lost settings, or Klipper refusing to
        # start on a parse error). Now: write a temporary file in the same folder, fsync, rename over the original
        # (atomic), fsync the folder. Identical content is not rewritten at all (fewer flash writes).
        buf = io.StringIO()
        varfile.write(buf)
        data = buf.getvalue().encode('utf-8')
        try:
            with open(self.filename, 'rb') as f:
                if f.read() == data:
                    return
        except OSError:
            pass
        dirname = os.path.dirname(os.path.abspath(self.filename))
        fd, tmp = tempfile.mkstemp(prefix='.saved_variables.', suffix='.tmp', dir=dirname)
        try:
            with os.fdopen(fd, 'wb') as f:
                try:
                    st = os.stat(self.filename)
                    os.fchmod(f.fileno(), stat.S_IMODE(st.st_mode))
                    try:
                        os.fchown(f.fileno(), st.st_uid if os.geteuid() == 0 else -1, st.st_gid)
                    except OSError:
                        pass
                except OSError:
                    os.fchmod(f.fileno(), 0o644)
                f.write(data)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, self.filename)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise
        try:
            dfd = os.open(dirname, os.O_DIRECTORY)
            try:
                os.fsync(dfd)
            finally:
                os.close(dfd)
        except OSError:
            pass

    def get_status(self, eventtime):  # q2-save-variables-atomic
        status = {'variables': self.allVariables}
